PRAGMA foreign_keys = ON;
CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','operator')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE products(product_version TEXT PRIMARY KEY, style_code TEXT NOT NULL, title TEXT NOT NULL, category_json TEXT NOT NULL DEFAULT '{}', deleting INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE device_events(id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, event_type TEXT NOT NULL, product_version TEXT REFERENCES products(product_version) ON DELETE CASCADE, device_id TEXT, review_id TEXT REFERENCES review_tasks(id) ON DELETE CASCADE, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, processed_at TEXT, checkpoint_id TEXT);
CREATE TABLE assets(id TEXT PRIMARY KEY, product_version TEXT NOT NULL REFERENCES products(product_version) ON DELETE CASCADE, r2_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('original','learning_thumbnail')), content_type TEXT NOT NULL, byte_size INTEGER NOT NULL, delete_after TEXT, created_at TEXT NOT NULL, UNIQUE(product_version,sha256,kind));
CREATE TABLE visual_facts(product_version TEXT PRIMARY KEY REFERENCES products(product_version) ON DELETE CASCADE, payload_json TEXT NOT NULL, model TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE text_facts(id TEXT PRIMARY KEY, product_version TEXT NOT NULL REFERENCES products(product_version) ON DELETE CASCADE, source TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE platform_fields(id TEXT PRIMARY KEY, platform_id TEXT NOT NULL, category_leaf_id TEXT NOT NULL, source_field_id TEXT NOT NULL, label TEXT NOT NULL, canonical_field TEXT, control_type TEXT NOT NULL, custom_allowed INTEGER NOT NULL DEFAULT 0, schema_version TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(platform_id,category_leaf_id,source_field_id,schema_version));
CREATE TABLE option_snapshots(snapshot_version TEXT PRIMARY KEY, platform_id TEXT NOT NULL, category_leaf_id TEXT NOT NULL, field_id TEXT NOT NULL, field_label TEXT NOT NULL, schema_version TEXT NOT NULL, custom_allowed INTEGER NOT NULL DEFAULT 0, options_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE attribute_decisions(id TEXT PRIMARY KEY, product_version TEXT NOT NULL REFERENCES products(product_version) ON DELETE CASCADE, platform_id TEXT NOT NULL, category_leaf_id TEXT NOT NULL, field_id TEXT NOT NULL, canonical_field TEXT, snapshot_version TEXT NOT NULL REFERENCES option_snapshots(snapshot_version), proposed_value_id TEXT, final_value_id TEXT, source TEXT NOT NULL, status TEXT NOT NULL, reason_code TEXT NOT NULL, evidence_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE conditional_rules(id TEXT PRIMARY KEY, platform_id TEXT NOT NULL, category_leaf_id TEXT NOT NULL, canonical_field TEXT NOT NULL, condition_signature TEXT NOT NULL, target_value_id TEXT NOT NULL, schema_version TEXT NOT NULL, consecutive_confirmations INTEGER NOT NULL DEFAULT 0, accepted_count INTEGER NOT NULL DEFAULT 0, total_count INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL CHECK(status IN ('observing','active','disabled')), updated_at TEXT NOT NULL, UNIQUE(platform_id,category_leaf_id,canonical_field,condition_signature));
CREATE TABLE review_tasks(id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, run_id TEXT NOT NULL, device_id TEXT NOT NULL, product_version TEXT NOT NULL REFERENCES products(product_version) ON DELETE CASCADE, platform_id TEXT NOT NULL, category_leaf_id TEXT NOT NULL, field_id TEXT NOT NULL, field_label TEXT NOT NULL, canonical_field TEXT, snapshot_version TEXT NOT NULL REFERENCES option_snapshots(snapshot_version), suggested_value_id TEXT, status TEXT NOT NULL CHECK(status IN ('pending','claimed','confirmed','resume_ready','consumed','invalidated')), reason_code TEXT NOT NULL, evidence_json TEXT NOT NULL DEFAULT '{}', claimed_by TEXT REFERENCES users(id), lease_until TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE review_actions(id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, review_id TEXT NOT NULL REFERENCES review_tasks(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), suggested_value_id TEXT, final_value_id TEXT NOT NULL, correction_reason TEXT, snapshot_version TEXT NOT NULL REFERENCES option_snapshots(snapshot_version), task_version INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(review_id,task_version));
CREATE TABLE run_checkpoints(run_id TEXT PRIMARY KEY, product_version TEXT NOT NULL REFERENCES products(product_version) ON DELETE CASCADE, device_id TEXT NOT NULL, execution_mode TEXT NOT NULL, platform_order_json TEXT NOT NULL, current_index INTEGER NOT NULL, status TEXT NOT NULL, pending_review_id TEXT REFERENCES review_tasks(id) ON DELETE SET NULL, version INTEGER NOT NULL DEFAULT 1, image_version TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE stage_results(idempotency_key TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES run_checkpoints(run_id) ON DELETE CASCADE, platform_id TEXT NOT NULL, status TEXT NOT NULL, expected_json TEXT NOT NULL, readback_json TEXT NOT NULL, verified INTEGER NOT NULL CHECK(verified IN (0,1)), updated_at TEXT NOT NULL, UNIQUE(run_id,platform_id));
CREATE TABLE persisted_readbacks(idempotency_key TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES run_checkpoints(run_id) ON DELETE CASCADE, product_version TEXT NOT NULL REFERENCES products(product_version) ON DELETE CASCADE, platform_id TEXT NOT NULL, field_id TEXT NOT NULL, snapshot_version TEXT REFERENCES option_snapshots(snapshot_version), actual_value_id TEXT, actual_label TEXT, verified INTEGER NOT NULL CHECK(verified IN (0,1)), payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX review_queue_idx ON review_tasks(status,created_at);
CREATE INDEX review_product_idx ON review_tasks(product_version,claimed_by);
CREATE INDEX rule_lookup_idx ON conditional_rules(platform_id,category_leaf_id,canonical_field,condition_signature);
CREATE INDEX asset_expiry_idx ON assets(kind,delete_after);
CREATE INDEX device_resume_idx ON device_events(device_id,event_type,processed_at);
CREATE INDEX session_user_idx ON sessions(user_id,expires_at);
CREATE INDEX checkpoint_product_idx ON run_checkpoints(product_version);
CREATE INDEX decision_product_idx ON attribute_decisions(product_version);
CREATE INDEX readback_product_idx ON persisted_readbacks(product_version);
